-- Fan the source projects' documents out onto the cloned rows
INSERT INTO public.projects_documents (project_id, title, type, url, privacy, position)
SELECT DISTINCT np.id, d.title, d.type, d.url, d.privacy, d.position
FROM public.projects np
JOIN public.projects op
  ON op.attributes->>'source_project_id' = np.attributes->>'source_project_id' AND op.id <> np.id
JOIN public.projects_documents d ON d.project_id = op.id
WHERE np.user_id IN (SELECT id FROM auth.users WHERE raw_user_meta_data->>'seed_batch' = 'promoteurs_289')
  AND NOT EXISTS (
    SELECT 1 FROM public.projects_documents x WHERE x.project_id = np.id AND x.url = d.url
  );

-- Profile city = most frequent city across the promoteur's projects
UPDATE public.profiles p SET location = (
  SELECT pr.city FROM public.projects pr
  WHERE pr.user_id = p.id AND pr.city IS NOT NULL AND pr.city <> ''
  GROUP BY pr.city ORDER BY count(*) DESC LIMIT 1
)
WHERE p.id IN (SELECT id FROM auth.users WHERE raw_user_meta_data->>'seed_batch' = 'promoteurs_289')
  AND EXISTS (SELECT 1 FROM public.projects pr WHERE pr.user_id = p.id AND pr.city IS NOT NULL AND pr.city <> '');

COMMIT;

